(function(root){'use strict';
const catalog=[{id:'template-trend',title:'趋势策略研究模板',kind:'策略学习模板',concept:'样本外验证',requires:[],status:'active',access:'local',fee:'免费',description:'定义趋势信号 → 划分训练/验证样本 → 加入换手费用 → 记录不同市场状态的表现。仅用于模拟研究。'},{id:'template-value',title:'价值假设研究模板',kind:'策略学习模板',concept:'未来数据泄漏',requires:[],status:'active',access:'local',fee:'免费',description:'明确估值尺度 → 核对发布时间 → 分组检验 → 检查行业偏差与价值陷阱。仅用于模拟研究。'},{id:'template-defense',title:'低波动配置实验',kind:'策略学习模板',concept:'资金占用',requires:[],status:'active',access:'local',fee:'免费',description:'定义波动窗口 → 设置预算与集中度 → 观察回撤和费用 → 与简单基准比较。低波动不等于保本。'},{id:'template-research',title:'消息调查工作单',kind:'策略学习模板',concept:'未来数据泄漏',requires:[],status:'active',access:'local',fee:'免费',description:'查消息来源、发布时间和独立证据，再决定是否行动。'},{id:'course-cost',title:'净收益与交易成本',kind:'微课程',concept:'交易成本',requires:[],status:'active',access:'local',fee:'免费',description:'区分毛结果、费用、净结果，用小实验核对账本。'}];
function validate(result,state){if(result.mode!=='mock'&&result.mode!=='ai')throw Error('画像来源无效');const ids=new Set(state.evidence.map(e=>e.id));if(!Array.isArray(result.labels)||result.labels.length>12)throw Error('标签数量无效');for(const l of result.labels){if(!/^[a-z][a-z0-9_-]{0,39}$/.test(l.id)||!l.text||!l.context||!Array.isArray(l.evidence_ids)||!l.evidence_ids.length||l.evidence_ids.some(x=>!ids.has(x)))throw Error('画像缺少有效证据');}for(const r of result.recommendations)if(!catalog.some(c=>c.id===r.resource_id&&c.status==='active'&&c.access==='local'))throw Error('推荐目录无效');return result;}
function analyze(s){const labels=[],groups={trend:[],value:[],defense:[],research:[]},meta={trend:['趋势型','趋势交易员·赤霄'],value:['价值型','价值买手·知夏'],defense:['防守型','现金守门员·凛川'],research:['研究型','研究分析师·星澜']};for(const e of s.evidence.filter(e=>e.dimension==='attribute'))if(groups[e.value])groups[e.value].push(e);for(const [id,ev] of Object.entries(groups))if(ev.length)labels.push({id:'type_'+id,text:meta[id][0]+' · '+meta[id][1],evidence_ids:ev.map(e=>e.id),context:'选择和建设共 '+ev.length+' 点',status:s.analystCorrections?.['type_'+id]?.status||'candidate',edited:s.analystCorrections?.['type_'+id]?.text||null});const district=s.city?.districts?.[0],resource=district?'template-'+district.id:'template-trend',top=Object.entries(groups).sort((a,b)=>b[1].length-a[1].length)[0];return validate({mode:'mock',version:4,labels,narrative:top[1].length?`最终是${meta[top[0]][0]}，最像${meta[top[0]][1]}。总分 ${top[1].length}。`:'还没有可统计的选择。',recommendations:[{resource_id:resource,reason:'这是你已经加过点的类型，可以继续试。'},{resource_id:'course-cost',reason:'看懂钱怎么赚、怎么亏。'}]},s);}
root.ProfileAnalyst={catalog,validate,analyze};if(typeof module!=='undefined')module.exports=root.ProfileAnalyst;
})(typeof window==='undefined'?globalThis:window);
